    if args.glob:
        files = glob_module.glob(args.glob)
    else:
        files = [sys.stdin]

    if not files:
        if args.fail_no_files:
            sys.exit(1)
        return

    match_count = 0
    files_with_matches = []

    for filepath in files:
        if filepath == sys.stdin:
            content = sys.stdin.read()
            filename = "<stdin>"
        else:
            try:
                with open(filepath, 'r') as f:
                    content = f.read()
                filename = filepath
            except IOError:
                continue

        if not content:
            continue

        scope = args.scope
        if args.literal_string:
            regex = re.compile(re.escape(scope))
        else:
            regex = re.compile(scope)

        lines = content.splitlines(keepends=True)
        if not lines[-1] or not lines[-1].endswith('\\n'):
            lines[-1] += '\\n'

        output_lines = []
        line_count = 0
        file_has_match = False

        for line in lines:
            line_count += 1
            if regex.search(line):
                file_has_match = True
                if args.only_matching:
                    output_lines.append(regex.sub(r'\\1', line))
